-- ============================================================================
-- SUPABASE POSTGRESQL SCHEMA & INITIAL DATA
-- Portal Penelitian Dosen Politeknik Negeri Lhokseumawe (PNL)
-- Terintegrasi PDDikti Kemdiktisaintek
-- Total: 314 Dosen & 1564 Judul Penelitian
-- ============================================================================

-- 1. Buat Tabel dosen
DROP TABLE IF EXISTS penelitian CASCADE;
DROP TABLE IF EXISTS dosen CASCADE;

CREATE TABLE dosen (
    id BIGINT PRIMARY KEY,
    pddikti_id VARCHAR(150),
    nama_dosen VARCHAR(255) NOT NULL,
    nidn VARCHAR(50),
    nuptk VARCHAR(50),
    perguruan_tinggi VARCHAR(255) DEFAULT 'Politeknik Negeri Lhokseumawe',
    jurusan VARCHAR(100) NOT NULL,
    program_studi VARCHAR(150) NOT NULL,
    jenjang VARCHAR(20) DEFAULT 'D4',
    jenis_kelamin VARCHAR(20) DEFAULT 'Laki-laki',
    jabatan_fungsional VARCHAR(100) DEFAULT 'Lektor',
    pendidikan_terakhir VARCHAR(20) DEFAULT 'S2',
    status_ikatan_kerja VARCHAR(100) DEFAULT 'Dosen Tetap',
    status_aktivitas VARCHAR(50) DEFAULT 'Aktif',
    status_pegawai VARCHAR(50) DEFAULT 'PNS',
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE INDEX idx_dosen_nama ON dosen (nama_dosen);
CREATE INDEX idx_dosen_jurusan ON dosen (jurusan);
CREATE INDEX idx_dosen_prodi ON dosen (program_studi);
CREATE INDEX idx_dosen_nidn ON dosen (nidn);

-- 2. Buat Tabel penelitian
CREATE TABLE penelitian (
    id BIGSERIAL PRIMARY KEY,
    dosen_id BIGINT NOT NULL REFERENCES dosen(id) ON DELETE CASCADE,
    judul_penelitian TEXT NOT NULL,
    tahun INT NOT NULL,
    jenis_kegiatan VARCHAR(100) DEFAULT 'Penelitian',
    sumber VARCHAR(255) DEFAULT 'PDDikti Kemdiktisaintek',
    created_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE INDEX idx_penelitian_dosen ON penelitian (dosen_id);
CREATE INDEX idx_penelitian_tahun ON penelitian (tahun);

-- 3. Enable Row Level Security (RLS) & Berikan Akses Publik Baca
ALTER TABLE dosen ENABLE ROW LEVEL SECURITY;
ALTER TABLE penelitian ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Allow public read for dosen" ON dosen FOR SELECT USING (true);
CREATE POLICY "Allow public read for penelitian" ON penelitian FOR SELECT USING (true);
CREATE POLICY "Allow all for service role on dosen" ON dosen FOR ALL USING (true);
CREATE POLICY "Allow all for service role on penelitian" ON penelitian FOR ALL USING (true);
CREATE POLICY "Allow anon insert on dosen" ON dosen FOR INSERT WITH CHECK (true);
CREATE POLICY "Allow anon update on dosen" ON dosen FOR UPDATE USING (true);
CREATE POLICY "Allow anon insert on penelitian" ON penelitian FOR INSERT WITH CHECK (true);
CREATE POLICY "Allow anon delete on penelitian" ON penelitian FOR DELETE USING (true);

-- 4. Masukkan Data 314 Dosen PNL

-- 5. Masukkan Data 1.564 Judul Penelitian PNL







-- Set sequence counter for auto-increment in Postgres
SELECT setval('penelitian_id_seq', (SELECT MAX(id) FROM penelitian));
